#include <functional>

int firstBad(int count, const std::function<bool(int)>& isBad)
{
    int good{ 0 };              // known good
    int bad{ count - 1 };       // known bad
    while (bad - good > 1)
    {
        const int middle{ good + (bad - good) / 2 };
        if (isBad(middle)) bad = middle;
        else good = middle;
    }
    return bad;
}

unitTests:
static int g_tests{ 0 };
static std::function<bool(int)> breaksAt(int first) { return [first](int n) { ++g_tests; return n >= first; }; }
TEST("the example") { g_tests = 0; CHECK_EQ(firstBad(10, breaksAt(6)), 6); }
TEST("the last build") { CHECK_EQ(firstBad(10, breaksAt(9)), 9); }
TEST("the second build") { CHECK_EQ(firstBad(10, breaksAt(1)), 1); }
TEST("only two builds") { g_tests = 0; CHECK_EQ(firstBad(2, breaksAt(1)), 1); CHECK_EQ(g_tests, 0); }
TEST("few tests on a long history")
{
    g_tests = 0;
    CHECK_EQ(firstBad(1'000'000, breaksAt(777'777)), 777'777);
    CHECK(g_tests <= 20);
}
TEST("never tests the known ends")
{
    bool touchedEnds{ false };
    firstBad(100, [&](int n) { if (n == 0 || n == 99) touchedEnds = true; return n >= 40; });
    CHECK(!touchedEnds);
}

